Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

const int MAXN=300010;
int n, K, mod;
int tableDP[MAXN][20];
int countBitsArr[MAXN], maxPowerArr[MAXN];
int factArr[MAXN], invFactArr[MAXN];

int fastExponentiation(int base, int exp) {
    int res=1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return res;
}

int binomial(int i, int j) {
    return (long long)factArr[i] * invFactArr[j] % mod * invFactArr[i - j] % mod;
}

int main() {
    scanf("%d%d%d", &n, &K, &mod);
    int i, j, k;
    int totalResult=0;
    int mask, remaining, tmpVal, current, c1, c2;

    if (n & 1) {
        printf("%d\n", fastExponentiation(K, n));
        return 0;
    }

    factArr[0]=1;
    for (i=1; i<=n; i++) factArr[i] = (long long)factArr[i-1]*i % mod;

    invFactArr[n] = fastExponentiation(factArr[n], mod-2);
    for (i=n-1; i>=1; i--) invFactArr[i] = (long long)invFactArr[i+1]*(i+1) % mod;

    for (i=1; i<=n; i++) {
        for (j=0; j<=18; j++) {
            if ((1<<j) & i) countBitsArr[i]++;
        }
    }

    for (i=1; i<=n; i++) {
        for (j=18; j>=0; j--) {
            if ((1<<j) & i) {
                maxPowerArr[i] = 1<<j;
                break;
            }
        }
    }

    memset(tableDP, 0, sizeof(tableDP));
    tableDP[0][0] = 1;

    for (i=1; i<=n; i++) {
        if ((n & i) != i) continue;
        remaining = i ^ maxPowerArr[i];
        for (mask=remaining; ; mask=(mask-1)&remaining) {
            current = mask + maxPowerArr[i];
            c2 = i ^ current;
            int limit = min(K-1, countBitsArr[c2]);
            int tmpVal = binomial(i, current);
            for (j=0; j<=limit; j++) {
                tableDP[i][j+1] = (tableDP[i][j+1] + (long long)tableDP[c2][j] * tmpVal) % mod;
            }
            if (mask == 0) break;
        }
    }

    for (j=1; j<=min(countBitsArr[n], K); j++) {
        totalResult = (totalResult + (long long)tableDP[n][j] * binomial(K, j) % mod * factArr[j]) % mod;
    }

    totalResult = (fastExponentiation(K, n) - totalResult + mod) % mod;
    printf("%d\n", totalResult);
    return 0;
}
